export const SupportInputSchema = {};
export const SupportOutputSchema = {};
export const SummaryOutputSchema = {};
export const FindOrderInputSchema = {};
export const FindOrderOutputSchema = {};

import { tool } from 'ai';
import { FindOrderInputSchema, FindOrderOutputSchema } from './contracts.js';
import { findOrder } from './implementations.js';
export const findOrderTool = tool({ inputSchema: FindOrderInputSchema, outputSchema: FindOrderOutputSchema, execute: findOrder });

import { generateText, Output, streamText, ToolLoopAgent } from 'ai';
import { FindOrderInputSchema, SupportInputSchema, SupportOutputSchema, SummaryOutputSchema } from './contracts.js';
import { loadSummaryInstruction, loadSupportInstruction } from './instructions.js';
import { findOrderTool } from './tools.js';
export const supportAgent = new ToolLoopAgent({ id: 'support-runtime', instructions: loadSupportInstruction(), callOptionsSchema: SupportInputSchema, output: Output.object({ schema: SupportOutputSchema }), tools: { find_order: findOrderTool } });
export const summaryAgent = async () => streamText({ instructions: await loadSummaryInstruction(), output: Output.object({ schema: SummaryOutputSchema }), tools: { find_order: findOrderTool } });
void generateText;
void FindOrderInputSchema;
